"use client";
import { useState } from "react";
import { X } from "lucide-react";
import ConfigModal from "./config-modal";
import type { CategoryMedia } from "./room-types";

// Photos and videos for each seater category (PG). Rooms themselves are generated by the floor generator,
// so this popup only manages the media shared by all rooms of a category. Works on a draft until "Save media".
export default function CategoryMediaModal({ categories, categoryMedia, onSave, onClose }: {
  categories: { capacity: number; rooms: number }[];
  categoryMedia: CategoryMedia[];
  onSave: (media: CategoryMedia[]) => void;
  onClose: () => void;
}) {
  const [media, setMedia] = useState<CategoryMedia[]>(categoryMedia);
  const [warn, setWarn] = useState("");

  const addMedia = (capacity: number, mediaType: "IMAGE" | "VIDEO", files: FileList | null) => {
    const picked = Array.from(files ?? []);
    const current = media.filter((m) => m.capacity === capacity && m.mediaType === mediaType).length;
    const limit = mediaType === "IMAGE" ? 10 : 5;
    if (current + picked.length > limit) { setWarn(`${capacity} seater category allows up to ${limit} ${mediaType === "IMAGE" ? "photos" : "videos"}.`); return; }
    setMedia((items) => [...items, ...picked.map((file) => ({ capacity, mediaType, file, originalName: file.name, src: URL.createObjectURL(file) }))]);
    setWarn("");
  };

  return (
    <ConfigModal title="Category photos & videos" subtitle="Shared by every room of the same seater category" onClose={onClose} onSave={() => onSave(media)} saveLabel="Save media">
      {warn && <p role="alert" className="mb-4 rounded-2xl bg-destructive/10 px-5 py-3 text-sm text-destructive">{warn}</p>}
      {categories.length === 0
        ? <p className="rounded-2xl bg-cream/60 px-5 py-6 text-center text-sm text-muted-foreground">Generate floors first. Media is kept per seater category.</p>
        : (
          <div className="space-y-4">
            {categories.map(({ capacity, rooms }) => (
              <div key={capacity} className="rounded-2xl border border-cream p-4">
                <div className="mb-3 flex items-center justify-between">
                  <div>
                    <p className="font-medium">{capacity} seater room media</p>
                    <p className="text-xs text-muted-foreground">Shared by all {rooms} rooms in this category</p>
                  </div>
                  <span className="text-xs text-muted-foreground">{media.filter((m) => m.capacity === capacity).length} files</span>
                </div>
                <div className="grid gap-3 sm:grid-cols-2">
                  <label className="cursor-pointer rounded-xl bg-cream px-4 py-3 text-center text-sm">Add photos<input type="file" accept="image/jpeg,image/png,image/webp" multiple className="hidden" onChange={(e) => { addMedia(capacity, "IMAGE", e.target.files); e.target.value = ""; }} /></label>
                  <label className="cursor-pointer rounded-xl bg-cream px-4 py-3 text-center text-sm">Add videos<input type="file" accept="video/mp4,video/webm" multiple className="hidden" onChange={(e) => { addMedia(capacity, "VIDEO", e.target.files); e.target.value = ""; }} /></label>
                </div>
                <div className="mt-3 grid grid-cols-2 gap-3 sm:grid-cols-4">
                  {media.filter((m) => m.capacity === capacity).map((item) => (
                    <div key={item.id ?? item.src} className="relative overflow-hidden rounded-xl bg-cream">
                      {item.mediaType === "IMAGE" ? <img src={item.src} alt={item.originalName} className="aspect-[4/3] w-full object-cover" /> : <video src={item.src} controls className="aspect-[4/3] w-full object-cover" />}
                      <button type="button" onClick={() => setMedia((items) => items.filter((m) => m !== item))} className="absolute right-2 top-2 rounded-full bg-background p-1.5 text-destructive"><X className="h-4 w-4" /></button>
                      <p className="truncate px-2 py-1 text-xs">{item.originalName}</p>
                    </div>
                  ))}
                </div>
                <p className="mt-2 text-xs text-muted-foreground">Maximum 10 photos (5 MB each) and 5 videos (50 MB each).</p>
              </div>
            ))}
          </div>
        )}
    </ConfigModal>
  );
}
